styles.css:
@font-face{font-family:"Noto Sans KR";src:url("assets/fonts/NotoSansKR.ttf") format("truetype");font-weight:100 900;font-style:normal;font-display:swap;}
*{box-sizing:border-box}body{margin:0;color:#202024;background:#fff;font-family:"Noto Sans KR",sans-serif;font-weight:500}button,input,select{font:inherit}button,a{-webkit-tap-highlight-color:transparent}button{cursor:pointer}img{display:block;max-width:100%}p,h1,h2,h3{margin:0}button:focus-visible,a:focus-visible{outline:3px solid #5146d7;outline-offset:4px}.site-header{height:64px;border-bottom:1px solid #ededf0;display:flex;align-items:center;max-width:1120px;margin:auto;padding:0 24px;font-size:20px;font-weight:800}.product{max-width:1120px;margin:40px auto;display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:48px;padding:0 24px}.details{min-width:0}.disclosure{max-width:1120px;margin:32px auto;padding:0 24px 32px;font-size:14px;color:#60606a;line-height:1.7}@media(max-width:700px){.site-header{height:52px;padding:0 20px;font-size:18px}.product{display:block;margin:0;padding:0}.details{padding:0 20px}.disclosure{padding:0 20px 24px;margin-top:24px}}
[data-ui-unit="media"].product-media { margin: 0; width: 100%; aspect-ratio: 1 / 1; overflow: hidden; }
[data-ui-unit="media"].product-media img { width: 100%; height: 100%; object-fit: cover; object-position: 44% center; display: block; }
@media (min-width: 701px) {
  [data-ui-unit="media"].product-media { border-radius: 8px; }
}
[data-ui-unit="identity"].product-identity {
  padding-top: 24px;
  padding-bottom: 24px;
}

@media (min-width: 701px) {
  [data-ui-unit="identity"].product-identity {
    padding-top: 0;
  }
}

[data-ui-unit="identity"] .eyebrow {
  font-size: 14px;
  color: #555560;
  margin-bottom: 8px;
}

[data-ui-unit="identity"] .title {
  font-family: "Noto Sans KR", sans-serif;
  font-weight: 700;
  line-height: 1.45;
  margin: 0;
  color: #202024;
}

@media (min-width: 701px) {
  [data-ui-unit="identity"] .title {
    font-size: 28px;
  }
}

@media (max-width: 700px) {
  [data-ui-unit="identity"] .title {
    font-size: 22px;
  }
}

[data-ui-unit="identity"] .price-row {
  margin-top: 12px;
}

[data-ui-unit="identity"] .price {
  display: block;
  font-family: "Noto Sans KR", sans-serif;
  font-weight: 800;
  font-size: 24px;
  color: #202024;
  line-height: 1.3;
}

[data-ui-unit="identity"] .metadata {
  margin-top: 24px;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

[data-ui-unit="identity"] .meta-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  color: #555560;
}

[data-ui-unit="identity"] .icon-clock,
[data-ui-unit="identity"] .icon-users,
[data-ui-unit="identity"] .icon-map-pin {
  width: 20px;
  height: 20px;
  display: block;
}

[data-ui-unit="identity"] .description {
  margin-top: 20px;
  font-size: 15px;
  line-height: 1.75;
  color: #202024;
}
[data-ui-unit="booking"] {
  display: block;
  width: 100%;
}

[data-ui-unit="booking"] .booking-host {
  border-top: 1px solid #ededf0;
  padding: 20px 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

[data-ui-unit="booking"] .booking-host-title {
  font-size: 16px;
  font-weight: 700;
  color: #202024;
  margin: 0;
  line-height: 1.3;
}

[data-ui-unit="booking"] .booking-host-subtitle {
  font-size: 14px;
  color: #60606a;
  margin: 0;
  line-height: 1.4;
}

[data-ui-unit="booking"] .booking-action-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
  padding-top: 20px;
}

@media (min-width: 600px) {
  [data-ui-unit="booking"] .booking-action-row {
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
  }
}

[data-ui-unit="booking"] .booking-icon-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border: none;
  background: transparent;
  padding: 0;
  cursor: pointer;
  transition: background-color 0.15s ease;
}

[data-ui-unit="booking"] .booking-icon-btn img {
  width: 24px;
  height: 24px;
  display: block;
  pointer-events: none;
}

[data-ui-unit="booking"] .booking-icon-btn:hover {
  background-color: #f4f4f6;
}

[data-ui-unit="booking"] .booking-icon-btn:focus-visible {
  outline: 3px solid #5146d7;
  outline-offset: 2px;
}

[data-ui-unit="booking"] .booking-icon-btn[aria-pressed="true"] img {
  filter: invert(27%) sepia(98%) saturate(1000%) hue-rotate(270deg) brightness(1.1) contrast(1.1);
}

[data-ui-unit="booking"] .booking-primary-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 52px;
  background-color: #5146d7;
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.1s ease;
}

[data-ui-unit="booking"] .booking-primary-btn:hover {
  background-color: #4338c2;
}

[data-ui-unit="booking"] .booking-primary-btn:active {
  transform: scale(0.98);
  background-color: #3b31a6;
}

[data-ui-unit="booking"] .booking-primary-btn:focus-visible {
  outline: 3px solid #5146d7;
  outline-offset: 2px;
}

[data-ui-unit="booking"] .booking-note {
  font-size: 14px;
  color: #60606a;
  line-height: 1.6;
  margin-top: 12px;
  margin-bottom: 0;
}
